using System;

public class Program
{
    public static double DiscountMinPrice(double price1, double price2, double price3)
    {
        double min = Math.Min(price1, Math.Min(price2, price3));
        return price1 + price2 + price3 - min;
    }

    public static void Main()
    {
        double a = double.Parse(Console.ReadLine());
        double b = double.Parse(Console.ReadLine());
        double c = double.Parse(Console.ReadLine());
        Console.WriteLine(DiscountMinPrice(a, b, c));
    }
}

