using System;

public class Program
{
    public static int GradesAbove90(int grade1, int grade2, int grade3)
    {
        int count = 0;
        if (grade1 > 90) count++;
        if (grade2 > 90) count++;
        if (grade3 > 90) count++;
        return count;
    }

    public static void Main()
    {
        int a = int.Parse(Console.ReadLine());
        int b = int.Parse(Console.ReadLine());
        int c = int.Parse(Console.ReadLine());
        Console.WriteLine(GradesAbove90(a, b, c));
    }
}
